import React, { useState } from "react";
import "./LoginPage.css";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = async (e) => {
  e.preventDefault();

  try {
    const res = await fetch("http://localhost:5000/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password })
    });

    const data = await res.json();
    console.log(data);

    if (res.ok) {
      // ✅ Store the CUSTOM userId (e.g., "EMP001"), NOT MongoDB _id
      localStorage.setItem("userId", data.user.d);  
      localStorage.setItem("role", data.role);

      // Optional: Store full user for faster dashboard load
      localStorage.setItem("currentUser", JSON.stringify(data.user));

      if (data.role === "admin") {
        window.location.href = "/admin-dashboard";
      } else {
        window.location.href = "/user-dashboard";
      }
    } else {
      alert(data.message || "Login failed");
    }
  } catch (error) {
    alert("Server error");
    console.error(error);
  }
};


  return (
    <div className="login-wrapper">
      {/* Background Animation */}
      <div className="bg-shape pink"></div>
      <div className="bg-shape blue"></div>

      <div className="login-card">
        <h2>Welcome Back 👋</h2>
        <p className="subtitle">Login to continue</p>

        <form onSubmit={handleSubmit}>
          <div className="input-group">
            <label>Email</label>
            <input
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="input-group">
            <label>Password</label>
            <input
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="login-btn">
            Login
          </button>
        </form>

      </div>
    </div>
  );
}
